import{_ as d,o as r,c as o,a2 as e}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"AI 绘画学习工作流 — 文档集","description":"","frontmatter":{},"headers":[],"relativePath":"README.md","filePath":"README.md"}'),a={name:"README.md"};function h(n,t,l,i,s,m){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="ai-绘画学习工作流-—-文档集" tabindex="-1">AI 绘画学习工作流 — 文档集</h1><p>用 AI 重绘自己的作品获得绘画反馈的完整工作流。硬件基线：RTX 4060 8GB（本机）+ AutoDL 按需租卡（训练用）。</p><blockquote><p><strong>墓志铭（写在最前面）</strong>：这些文档是心智模型，是脚手架，是&quot;防止走歪路的拐杖&quot;（你的原话）——<strong>不是收藏品，用完即弃</strong>。你的方法论说&quot;具体材料本身就是模型，绘画靠的是画笔不是笔记&quot;：文档的价值只存在于被实践的那一刻。若某天你发现自己又在读文档而不是画画，请把这句话读一遍，然后关机。</p></blockquote><h2 id="文档地图" tabindex="-1">文档地图</h2><table tabindex="0"><thead><tr><th>文档</th><th>内容</th><th>什么时候看</th></tr></thead><tbody><tr><td><a href="./01-心智模型与方法论.html">01-心智模型与方法论.md</a></td><td>三层模型、控制通道语义、反馈类型、浅/深拷贝模型、组件词典</td><td>先读，建立坐标系</td></tr><tr><td><a href="./02-安装手册.html">02-安装手册.md</a></td><td>ComfyUI + 节点 + 模型的完整安装（国内镜像加速，链接全部实测）</td><td>装机时</td></tr><tr><td><a href="./03-基线工作流-W1-NoobAI.html">03-基线工作流-W1-NoobAI.md</a></td><td>W1 双通道工作流、NoobAI 官方参数、提示词模板</td><td>跑第一张图时</td></tr><tr><td><a href="./04-平行基线-W2-W5.html">04-平行基线-W2-W5.md</a></td><td>四种备选工作流（FLUX.2 klein / Qwen-Edit / FLUX.2 dev / 老师风格）对照</td><td>第 3–4 周起</td></tr><tr><td><a href="./05-风格路线-IPAdapter.html">05-风格路线-IPAdapter.md</a></td><td>零训练风格跟随：心智模型 + 完整流程</td><td>想快速&quot;老师化&quot;你的画时</td></tr><tr><td><a href="./06-风格路线-LoRA.html">06-风格路线-LoRA.md</a></td><td>深拷贝风格训练：心智模型 + 数据准备 + 训练 + 部署</td><td>确定长期学某位老师时</td></tr><tr><td><a href="./07-学习闭环与归档.html">07-学习闭环与归档.md</a></td><td>自评→重绘→差异自读→短板雷达 的闭环与归档模板</td><td>每周</td></tr><tr><td><a href="./08-方法论验证.html">08-方法论验证.md</a></td><td>你的心智模型 vs 这套工作流 vs 外部实践（学术界/教育界/业界/反方观点）的证据清单</td><td>动摇时读</td></tr><tr><td><a href="./10-LoRA训练完整教程.html">10-LoRA训练完整教程.md</a></td><td>AutoDL 无卡模式→GPU 训练→回收验证的完整实操（每一步知其所以然）</td><td>训练 LoRA 时</td></tr><tr><td><a href="./11-资源链接大全.html">11-资源链接大全.md</a></td><td>模型/工作流/社区/官方/云服务 的全部链接（含验证标注）</td><td>找资源时</td></tr><tr><td><a href="./12-自动化蓝图.html">12-自动化蓝图.md</a></td><td>Krita→ComfyUI API→AutoDL 的全自动管线规划（未来阶段）</td><td>第 4 周以后</td></tr></tbody></table><h2 id="方法论总纲-一句话版" tabindex="-1">方法论总纲（一句话版）</h2><blockquote><p><strong>业务层选通道、参数层用默认、对比层才较真。</strong></p></blockquote><ol><li><strong>业务层</strong>（第 1–4 周）：搭工作流，在工作流之间比较（ControlNet 强度、denoise、参考图通道、LoRA 通道）</li><li><strong>参数层</strong>（第 5 周起）：才允许动 CFG / 步数 / 采样器，每次只变一个</li><li><strong>对比层</strong>（最后）：严格的 A/B，仅用于解决具体问题</li></ol><p>两条核心认知（详见 01）：</p><ul><li><strong>提示词是&quot;描述&quot;不是&quot;指令&quot;</strong>——结构修正靠 ControlNet 强度 × denoise × 负向提示词，不靠句子</li><li><strong>反馈分两类</strong>：隐性纠错（贴线重绘，发现盲区）vs 显性纠错（指令修图，验证诊断）</li></ul><h2 id="路线图" tabindex="-1">路线图</h2><table tabindex="0"><thead><tr><th>阶段</th><th>目标</th><th>动作</th></tr></thead><tbody><tr><td>第 1 周</td><td>跑通 W1</td><td>按 02 安装，按 03 出第一张重绘</td></tr><tr><td>第 2 周</td><td>双通道</td><td>A/B 并存，开始 07 的闭环循环</td></tr><tr><td>第 3–4 周</td><td>平行基线</td><td>装 W2（klein）跑通指令修图；<strong>IP-Adapter 路线（05）验证老师风格方向</strong>；对照隐性/显性纠错</td></tr><tr><td>第 5 周起</td><td>参数层</td><td>才允许动参数</td></tr><tr><td>第二阶段</td><td>风格深拷贝</td><td>确认老师后，按 06 准备数据 + 租卡训 LoRA（6 元/小时 × 1~2 小时 ≈ 10 元）</td></tr></tbody></table><h2 id="术语速查" tabindex="-1">术语速查</h2><table tabindex="0"><thead><tr><th>术语</th><th>一句话</th></tr></thead><tbody><tr><td>底模 / Checkpoint</td><td>模型的&quot;画师人格&quot;（UNet + CLIP + VAE 三件套）</td></tr><tr><td>VAE</td><td>潜空间 ↔ 像素的转换器（SDXL 自带即可，无需另下）</td></tr><tr><td>潜空间</td><td>模型实际工作的压缩空间（生成在压缩态进行）</td></tr><tr><td>ControlNet</td><td>结构控制通道：吃一张引导图（线稿/骨架），管&quot;长什么样&quot;</td></tr><tr><td>预处理器</td><td>把你的画翻译成 ControlNet 能读的引导图</td></tr><tr><td>denoise</td><td>img2img 的改动幅度旋钮（0.4–0.6 = 半贴线重画）</td></tr><tr><td>CFG / 步数 / 采样器</td><td>参数层旋钮，默认值：5 / 28 / Euler a（NoobAI）</td></tr><tr><td>IP-Adapter</td><td>零训练风格跟随适配器（浅拷贝，即时生效）</td></tr><tr><td>LoRA</td><td>训练过的风格/概念小补丁（深拷贝，一次训练长期复用）</td></tr><tr><td>WD14 Tagger</td><td>图 → Danbooru 标签（自动生成提示词/训练打标）</td></tr></tbody></table>',14)])])}const b=d(a,[["render",h]]);export{u as __pageData,b as default};
